//! rce C ABI.
//!
//! Stable surface for embedding rce from C, C++, Go (cgo), Swift, JVM
//! (JNI), and any other language with C interop. The header is auto-
//! generated by `cbindgen` at build time and lives at
//! `crates/rce-c/include/rce.h` for consumers.
//!
//! ## Memory ownership
//!
//! - Functions returning `*mut T` transfer ownership to the caller.
//!   Callers MUST free with the matching `rce_*_free`.
//! - Functions returning `char *` (UTF-8 strings, null-terminated)
//!   transfer ownership; free with `rce_string_free`.
//! - Inputs (`const uint8_t *`, `const char *`) are borrowed for the
//!   duration of the call only.
//!
//! ## Errors
//!
//! Every fallible function returns a `RceStatus`. On error, callers
//! can fetch a thread-local error message with `rce_last_error()`.
//! The message is overwritten on each new error in the same thread.

#![allow(non_camel_case_types)]

use std::cell::RefCell;
use std::ffi::{c_char, c_void, CStr, CString};
use std::io::Cursor;
use std::sync::Arc;

use rce_format::{graph_section, FgFile, SectionKind};
use rce_vm_backend_cpu::{
    interpret_with_config, Inputs, InterpretConfig, OpDispatch,
};
use rce_vm_backend_wgpu::WgpuExecutor;

thread_local! {
    static LAST_ERROR: RefCell<Option<CString>> = RefCell::new(None);
}

fn set_last_error(msg: impl Into<String>) {
    LAST_ERROR.with(|cell| {
        *cell.borrow_mut() = CString::new(msg.into()).ok();
    });
}

/// Status codes returned from every fallible function.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RceStatus {
    Ok = 0,
    /// Null pointer where a non-null pointer was required.
    NullArgument = 1,
    /// `.fg` parse / format error.
    Parse = 2,
    /// safetensors sidecar load error.
    Weights = 3,
    /// Interpret-time error (op unsupported, type mismatch, OOM, etc.).
    Interpret = 4,
    /// JSON input could not be parsed or did not match the graph's parameters.
    Inputs = 5,
    /// wgpu adapter could not be obtained.
    NoGpu = 6,
    /// Generic internal error; check `rce_last_error()`.
    Internal = 7,
}

/// An opaque module — a parsed `.fg` graph with optional bound weights.
pub struct RceModule {
    graph: rce_graph::graph::FunctionGraph,
}

/// An opaque VM — a CPU interpreter, optionally with a wgpu backend
/// pre-initialised. Handle is reusable across many `rce_run` calls.
pub struct RceVm {
    wgpu: Option<Arc<WgpuExecutor>>,
    cast_f32: bool,
}

/// Return a borrowed null-terminated string with the last error set on
/// this thread, or NULL if no error has occurred. The pointer is valid
/// until the next failing call on this thread.
///
/// # Safety
/// The returned pointer is valid for the lifetime of the calling thread
/// up to the next failing rce_* call. Do not free it.
#[unsafe(no_mangle)]
pub extern "C" fn rce_last_error() -> *const c_char {
    LAST_ERROR.with(|cell| {
        cell.borrow()
            .as_ref()
            .map_or(std::ptr::null(), |c| c.as_ptr())
    })
}

/// Free a string returned by `rce_run`.
///
/// # Safety
/// `s` must be a pointer returned by `rce_run` (or NULL); passing any
/// other pointer is undefined behaviour.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rce_string_free(s: *mut c_char) {
    if !s.is_null() {
        drop(unsafe { CString::from_raw(s) });
    }
}

/// Parse a `.fg` byte buffer (and optional safetensors sidecar) into an
/// opaque module handle. On success, `*out_module` is set to a heap-
/// allocated `RceModule` that the caller must free with
/// `rce_module_free`.
///
/// # Safety
/// `fg_bytes` must point to `fg_len` readable bytes. If `st_bytes` is
/// non-NULL, it must point to `st_len` readable bytes. `out_module`
/// must be a valid `*mut *mut RceModule`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rce_module_load(
    fg_bytes: *const u8,
    fg_len: usize,
    st_bytes: *const u8,
    st_len: usize,
    out_module: *mut *mut RceModule,
) -> RceStatus {
    if fg_bytes.is_null() || out_module.is_null() {
        set_last_error("null argument");
        return RceStatus::NullArgument;
    }
    let fg = unsafe { std::slice::from_raw_parts(fg_bytes, fg_len) };
    let file = match FgFile::read(Cursor::new(fg)) {
        Ok(f) => f,
        Err(e) => {
            set_last_error(format!("parse .fg: {e}"));
            return RceStatus::Parse;
        }
    };
    let graph_section = match file.section(SectionKind::Graph) {
        Some(s) => s,
        None => {
            set_last_error(".fg has no Graph section");
            return RceStatus::Parse;
        }
    };
    let mut graph: rce_graph::graph::FunctionGraph =
        match graph_section::graph_from_section(graph_section) {
            Ok(g) => g,
            Err(e) => {
                set_last_error(format!("decode graph: {e}"));
                return RceStatus::Parse;
            }
        };

    if !st_bytes.is_null() && st_len > 0 {
        let st = unsafe { std::slice::from_raw_parts(st_bytes, st_len) };
        match rce_weight_loader::SafetensorsFile::from_bytes(st) {
            Ok(loaded) => {
                if let Err(e) = reattach_weights(&mut graph, &loaded) {
                    set_last_error(format!("reattach: {e}"));
                    return RceStatus::Weights;
                }
            }
            Err(e) => {
                set_last_error(format!("safetensors: {e}"));
                return RceStatus::Weights;
            }
        }
    }

    let m = Box::new(RceModule { graph });
    unsafe { *out_module = Box::into_raw(m); }
    RceStatus::Ok
}

fn reattach_weights(
    graph: &mut rce_graph::graph::FunctionGraph,
    st: &rce_weight_loader::SafetensorsFile,
) -> Result<(), String> {
    use rce_graph::graph::GraphNode;
    for node in graph.nodes.iter_mut() {
        if let GraphNode::TensorLiteral(td) = node {
            if !td.data.is_empty() {
                continue;
            }
            let loaded = st
                .get(&td.name)
                .ok_or_else(|| format!("weight `{}` not in sidecar", td.name))?;
            if loaded.dtype != td.dtype || loaded.shape != td.shape {
                return Err(format!(
                    "weight `{}`: shape/dtype mismatch (graph wants {:?}/{}, sidecar has {:?}/{})",
                    td.name, td.shape, td.dtype, loaded.shape, loaded.dtype
                ));
            }
            td.data = loaded.data.to_arc();
        }
    }
    Ok(())
}

/// Free a module handle.
///
/// # Safety
/// `m` must be a pointer returned by `rce_module_load` (or NULL); any
/// other pointer is undefined behaviour. After this call `m` is invalid.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rce_module_free(m: *mut RceModule) {
    if !m.is_null() {
        drop(unsafe { Box::from_raw(m) });
    }
}

/// Construct a VM. Pass `try_wgpu = 1` to attempt wgpu initialisation;
/// the call still succeeds if wgpu is unavailable (CPU-only mode).
///
/// # Safety
/// `out_vm` must be a valid `*mut *mut RceVm`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rce_vm_new(
    try_wgpu: i32,
    out_vm: *mut *mut RceVm,
) -> RceStatus {
    if out_vm.is_null() {
        set_last_error("null out_vm");
        return RceStatus::NullArgument;
    }
    let wgpu = if try_wgpu != 0 {
        WgpuExecutor::new().ok().map(Arc::new)
    } else {
        None
    };
    let vm = Box::new(RceVm { wgpu, cast_f32: false });
    unsafe { *out_vm = Box::into_raw(vm); }
    RceStatus::Ok
}

/// Toggle automatic f64 → f32 input casting. The CPU runtime is dtype-
/// strict; if your graph expects f32 weights but you're sending f64
/// JSON inputs, set this to 1 and inputs are cast on entry. Equivalent
/// to the `--cast-f32` CLI flag.
///
/// # Safety
/// `vm` must be a valid handle from `rce_vm_new`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rce_vm_set_cast_f32(vm: *mut RceVm, on: i32) {
    if vm.is_null() { return; }
    unsafe { (*vm).cast_f32 = on != 0; }
}

/// Free a VM handle.
///
/// # Safety
/// `vm` must be a pointer returned by `rce_vm_new` (or NULL); any
/// other pointer is undefined behaviour.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rce_vm_free(vm: *mut RceVm) {
    if !vm.is_null() {
        drop(unsafe { Box::from_raw(vm) });
    }
}

/// Run a module against bound inputs. Inputs and outputs are JSON-
/// encoded; tensors are nested arrays (e.g. `{"x": [[1,2],[3,4]]}`).
/// On success, `*out_json` is set to a heap-allocated null-terminated
/// UTF-8 string the caller must free with `rce_string_free`.
///
/// # Safety
/// `vm` and `m` must be valid handles. `input_json` must be a non-null
/// null-terminated UTF-8 string. `out_json` must be a valid
/// `*mut *mut c_char`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rce_run(
    vm: *mut RceVm,
    m: *const RceModule,
    input_json: *const c_char,
    out_json: *mut *mut c_char,
) -> RceStatus {
    if vm.is_null() || m.is_null() || input_json.is_null() || out_json.is_null() {
        set_last_error("null argument");
        return RceStatus::NullArgument;
    }
    let vm: &RceVm = unsafe { &*vm };
    let module: &RceModule = unsafe { &*m };

    let input_str = match unsafe { CStr::from_ptr(input_json) }.to_str() {
        Ok(s) => s,
        Err(e) => {
            set_last_error(format!("input_json not valid UTF-8: {e}"));
            return RceStatus::Inputs;
        }
    };
    let mut inputs = match parse_inputs(input_str) {
        Ok(i) => i,
        Err(e) => {
            set_last_error(format!("inputs: {e}"));
            return RceStatus::Inputs;
        }
    };
    if vm.cast_f32 {
        for v in inputs.values_mut() {
            *v = cast_value_to_f32(v.clone());
        }
    }

    let ops_storage: Vec<&dyn OpDispatch> = match vm.wgpu.as_ref() {
        Some(arc) => vec![arc.as_ref()],
        None => Vec::new(),
    };
    let cfg = InterpretConfig {
        leaves: &[],
        ops: &ops_storage,
    };
    let value = match interpret_with_config(&module.graph, &inputs, cfg) {
        Ok(v) => v,
        Err(e) => {
            set_last_error(format!("interpret: {e}"));
            return RceStatus::Interpret;
        }
    };
    let out_str = value_to_json(&value);
    let c = match CString::new(out_str) {
        Ok(c) => c,
        Err(e) => {
            set_last_error(format!("output had nul byte: {e}"));
            return RceStatus::Internal;
        }
    };
    unsafe { *out_json = c.into_raw(); }
    RceStatus::Ok
}

fn cast_value_to_f32(v: rce_vm_backend_cpu::Value) -> rce_vm_backend_cpu::Value {
    use rce_vm_backend_cpu::tensor::DType;
    use rce_vm_backend_cpu::{HostTensor, ScalarValue, Value};
    match v {
        Value::Tensor(t) => {
            let dt = t.dtype;
            let shape = t.shape.clone();
            match dt {
                DType::F64 => {
                    let v: Vec<f32> = t
                        .as_f64()
                        .unwrap_or_default()
                        .into_iter()
                        .map(|x| x as f32)
                        .collect();
                    Value::Tensor(HostTensor::from_f32(shape, &v).unwrap_or(t))
                }
                DType::I64 => {
                    let v: Vec<f32> = t
                        .as_i64()
                        .unwrap_or_default()
                        .into_iter()
                        .map(|x| x as f32)
                        .collect();
                    Value::Tensor(HostTensor::from_f32(shape, &v).unwrap_or(t))
                }
                _ => Value::Tensor(t),
            }
        }
        Value::Scalar(ScalarValue::F64(x)) => Value::Scalar(ScalarValue::F32(x as f32)),
        Value::Scalar(ScalarValue::I64(x)) => Value::Scalar(ScalarValue::F32(x as f32)),
        other => other,
    }
}

fn parse_inputs(s: &str) -> Result<Inputs, String> {
    use rce_vm_backend_cpu::{HostTensor, ScalarValue, Value};
    use serde_json::Value as J;
    let raw: J = serde_json::from_str(s).map_err(|e| e.to_string())?;
    let obj = raw.as_object().ok_or("inputs must be JSON object")?;
    let mut out = Inputs::new();
    for (k, v) in obj {
        out.insert(k.clone(), json_to_value(v)?);
    }
    fn json_to_value(v: &J) -> Result<Value, String> {
        match v {
            J::Bool(b) => Ok(Value::Scalar(ScalarValue::Bool(*b))),
            J::Number(n) => {
                if let Some(i) = n.as_i64() {
                    Ok(Value::Scalar(ScalarValue::I64(i)))
                } else if let Some(f) = n.as_f64() {
                    Ok(Value::Scalar(ScalarValue::F64(f)))
                } else {
                    Err(format!("unparseable number: {n}"))
                }
            }
            J::String(s) => Ok(Value::Scalar(ScalarValue::String(s.clone()))),
            J::Array(_) => {
                let (shape, flat, all_integer) = flatten_json_array(v)?;
                // Promote to i64 only when every leaf was JSON-typed as
                // an integer (no decimal point). `1.0` is f64 even though
                // its fractional part is zero — that distinction matters
                // because the runtime is dtype-strict.
                if all_integer {
                    let v: Vec<i64> = flat.iter().map(|f| *f as i64).collect();
                    Ok(Value::Tensor(
                        HostTensor::from_i64(shape, &v).map_err(|e| format!("{e}"))?,
                    ))
                } else {
                    Ok(Value::Tensor(
                        HostTensor::from_f64(shape, &flat).map_err(|e| format!("{e}"))?,
                    ))
                }
            }
            J::Null => Err("null inputs not supported".into()),
            J::Object(_) => Err("nested object inputs not supported".into()),
        }
    }
    fn flatten_json_array(v: &J) -> Result<(Vec<usize>, Vec<f64>, bool), String> {
        let mut shape = Vec::new();
        let mut flat = Vec::new();
        let mut cursor = v;
        while let J::Array(a) = cursor {
            shape.push(a.len());
            if a.is_empty() {
                return Ok((shape, flat, true));
            }
            cursor = &a[0];
        }
        fn walk(
            v: &J,
            depth: usize,
            shape: &[usize],
            flat: &mut Vec<f64>,
            all_integer: &mut bool,
        ) -> Result<(), String> {
            match v {
                J::Array(a) => {
                    if a.len() != shape[depth] {
                        return Err(format!(
                            "ragged array at depth {depth}: expected {} got {}",
                            shape[depth],
                            a.len()
                        ));
                    }
                    for x in a {
                        walk(x, depth + 1, shape, flat, all_integer)?;
                    }
                    Ok(())
                }
                J::Number(n) => {
                    if n.is_f64() {
                        *all_integer = false;
                    }
                    flat.push(n.as_f64().ok_or("non-finite number")?);
                    Ok(())
                }
                _ => Err(format!("non-numeric leaf at depth {depth}")),
            }
        }
        let mut all_integer = true;
        walk(v, 0, &shape, &mut flat, &mut all_integer)?;
        Ok((shape, flat, all_integer))
    }
    Ok(out)
}

fn value_to_json(v: &rce_vm_backend_cpu::Value) -> String {
    use rce_vm_backend_cpu::{ScalarValue, Value};
    match v {
        Value::Scalar(ScalarValue::Bool(b)) => b.to_string(),
        Value::Scalar(ScalarValue::I32(x)) => x.to_string(),
        Value::Scalar(ScalarValue::I64(x)) => x.to_string(),
        Value::Scalar(ScalarValue::F32(x)) => serde_json::Number::from_f64(*x as f64)
            .map(|n| n.to_string())
            .unwrap_or_else(|| format!("{x}")),
        Value::Scalar(ScalarValue::F64(x)) => serde_json::Number::from_f64(*x)
            .map(|n| n.to_string())
            .unwrap_or_else(|| format!("{x}")),
        Value::Scalar(ScalarValue::String(s)) => serde_json::to_string(s).unwrap_or_default(),
        Value::Tensor(t) => tensor_to_json(t),
        Value::DeviceTensor(d) => format!(
            r#"{{"__device_tensor__":{{"device":"{}","dtype":"{}","shape":{:?},"bytes":{}}}}}"#,
            d.device.name(),
            d.dtype.name(),
            d.shape,
            d.size_bytes()
        ),
    }
}

fn tensor_to_json(t: &rce_vm_backend_cpu::HostTensor) -> String {
    use rce_vm_backend_cpu::tensor::DType;
    let nums: Vec<f64> = match t.dtype {
        DType::F32 => t.as_f32().map(|v| v.into_iter().map(|x| x as f64).collect()).unwrap_or_default(),
        DType::F64 => t.as_f64().unwrap_or_default(),
        DType::I32 => t.as_i32().map(|v| v.into_iter().map(|x| x as f64).collect()).unwrap_or_default(),
        DType::I64 => t.as_i64().map(|v| v.into_iter().map(|x| x as f64).collect()).unwrap_or_default(),
        DType::Bool => t.as_bool().map(|v| v.into_iter().map(|b| if b { 1.0 } else { 0.0 }).collect()).unwrap_or_default(),
        DType::F16 | DType::BF16 => Vec::new(),
    };
    fn build(nums: &[f64], shape: &[usize], offset: usize, stride_buf: &mut Vec<usize>) -> serde_json::Value {
        if shape.is_empty() {
            if let Some(n) = nums.get(offset) {
                return serde_json::Value::Number(
                    serde_json::Number::from_f64(*n).unwrap_or_else(|| serde_json::Number::from(0)),
                );
            }
            return serde_json::Value::Null;
        }
        let dim = shape[0];
        let stride: usize = shape[1..].iter().product::<usize>().max(1);
        let mut arr = Vec::with_capacity(dim);
        for i in 0..dim {
            arr.push(build(nums, &shape[1..], offset + i * stride, stride_buf));
        }
        serde_json::Value::Array(arr)
    }
    let mut sb = Vec::new();
    let v = if t.shape.is_empty() {
        if let Some(n) = nums.first() {
            serde_json::Value::Number(
                serde_json::Number::from_f64(*n).unwrap_or_else(|| serde_json::Number::from(0)),
            )
        } else {
            serde_json::Value::Null
        }
    } else {
        build(&nums, &t.shape, 0, &mut sb)
    };
    serde_json::to_string(&v).unwrap_or_default()
}

// Silence the unused-deps warning for the rlib facet.
#[allow(dead_code)]
fn _link_ref(_x: *const c_void) {}
